-- Seeds the 60 games from store.example.json into public.games.
-- created_at is omitted so the table default is used.

INSERT INTO public.games (
  id, title, genre, category, categories, description, image, link, tags
) VALUES
  ('hollow-knight', 'Hollow Knight', 'Action • Metroidvania', 'Adventure', ARRAY['Adventure', 'Action']::text[], 'Descend into Hallownest, a vast kingdom of forgotten insects and ancient secrets. Precision combat and winding caverns make every discovery feel earned.', 'https://cdn.akamai.steamstatic.com/steam/apps/367520/header.jpg', 'https://store.steampowered.com/app/367520/', ARRAY['indie', 'hand-drawn', 'challenging', 'exploration']::text[]),
  ('ori-and-the-blind-forest', 'Ori and the Blind Forest', 'Platformer • Adventure', 'Adventure', ARRAY['Adventure']::text[], 'Guide Ori through a beautifully hand-painted forest threatened by a spreading blight. Fluid platforming and an emotional story make this a memorable journey.', 'https://cdn.akamai.steamstatic.com/steam/apps/387290/header.jpg', 'https://store.steampowered.com/app/387290/', ARRAY['indie', 'platformer', 'fantasy', 'story rich']::text[]),
  ('ori-and-the-will-of-the-wisps', 'Ori and the Will of the Wisps', 'Platformer • Adventure', 'Adventure', ARRAY['Adventure']::text[], 'Explore a vast, strange world as Ori searches for a lost friend. New abilities, expressive characters, and demanding platforming deepen the adventure.', 'https://cdn.akamai.steamstatic.com/steam/apps/1057090/header.jpg', 'https://store.steampowered.com/app/1057090/', ARRAY['indie', 'platformer', 'fantasy', 'exploration']::text[]),
  ('celeste', 'Celeste', 'Platformer • Indie', 'Adventure', ARRAY['Adventure']::text[], 'Help Madeline climb Celeste Mountain through precise, screen-sized platforming challenges. Its intimate story explores anxiety, perseverance, and self-acceptance.', 'https://cdn.akamai.steamstatic.com/steam/apps/504230/header.jpg', 'https://store.steampowered.com/app/504230/', ARRAY['indie', 'pixel art', 'challenging', 'story rich']::text[]),
  ('sea-of-stars', 'Sea of Stars', 'RPG • Turn-based', 'RPG', ARRAY['RPG', 'Adventure']::text[], 'Join two Children of the Solstice on a vibrant quest to stop an ancient alchemist. This turn-based role-playing adventure pairs timing-based combat with handcrafted exploration.', 'https://cdn.akamai.steamstatic.com/steam/apps/1244090/header.jpg', 'https://store.steampowered.com/app/1244090/', ARRAY['indie', 'fantasy', 'turn-based', 'pixel art']::text[]),
  ('undertale', 'Undertale', 'RPG • Indie', 'RPG', ARRAY['RPG', 'Adventure']::text[], 'Descend into a monster-filled underground world and decide how you will treat its inhabitants. Your choices shape encounters, relationships, and the story''s outcome.', 'https://cdn.akamai.steamstatic.com/steam/apps/391540/header.jpg', 'https://store.steampowered.com/app/391540/', ARRAY['indie', 'story rich', 'choice-driven', 'pixel art']::text[]),
  ('cuphead', 'Cuphead', 'Run and Gun • Platformer', 'Action', ARRAY['Action', 'Adventure']::text[], 'Take on a series of demanding boss battles in a world inspired by 1930s cartoons. Its hand-drawn animation and energetic soundtrack frame a tough but fair challenge.', 'https://cdn.akamai.steamstatic.com/steam/apps/268910/header.jpg', 'https://store.steampowered.com/app/268910/', ARRAY['indie', 'boss rush', 'challenging', 'co-op']::text[]),
  ('journey', 'Journey', 'Adventure • Exploration', 'Adventure', ARRAY['Adventure']::text[], 'Travel across a vast desert toward a distant mountain in a wordless, atmospheric adventure. You may encounter another traveler online, sharing the journey without spoken communication.', 'https://cdn.akamai.steamstatic.com/steam/apps/638230/header.jpg', 'https://store.steampowered.com/app/638230/', ARRAY['indie', 'artistic', 'exploration', 'multiplayer']::text[]),
  ('stray', 'Stray', 'Adventure • Exploration', 'Adventure', ARRAY['Adventure', 'Puzzle']::text[], 'Explore a decaying cybercity as a stray cat separated from its family. Solve environmental puzzles, meet its robot residents, and find a way back outside.', 'https://cdn.akamai.steamstatic.com/steam/apps/1332010/header.jpg', 'https://store.steampowered.com/app/1332010/', ARRAY['cyberpunk', 'cats', 'exploration', 'puzzle']::text[]),
  ('limbo', 'Limbo', 'Puzzle • Platformer', 'Puzzle', ARRAY['Puzzle', 'Adventure', 'Horror']::text[], 'A boy searches a monochrome, perilous world for his sister. Environmental puzzles and minimalist sound design build an unsettling atmosphere.', 'https://cdn.akamai.steamstatic.com/steam/apps/48000/header.jpg', 'https://store.steampowered.com/app/48000/', ARRAY['indie', 'dark', 'platformer', 'atmospheric']::text[]),
  ('the-witcher-3', 'The Witcher 3: Wild Hunt', 'RPG • Open World', 'RPG', ARRAY['RPG', 'Adventure', 'Open World']::text[], 'Play as monster hunter Geralt in a sprawling fantasy world shaped by political conflict and personal choices. Contracts, exploration, and character-driven quests fill the journey.', 'https://cdn.akamai.steamstatic.com/steam/apps/292030/header.jpg', 'https://store.steampowered.com/app/292030/', ARRAY['fantasy', 'open world', 'story rich', 'choices']::text[]),
  ('skyrim', 'The Elder Scrolls V: Skyrim', 'RPG • Open World', 'RPG', ARRAY['RPG', 'Adventure', 'Open World']::text[], 'Explore the province of Skyrim as a Dragonborn in this open-ended fantasy role-playing game. Follow the main quest or build your own adventures across its mountains and towns.', 'https://cdn.akamai.steamstatic.com/steam/apps/489830/header.jpg', 'https://store.steampowered.com/app/489830/', ARRAY['fantasy', 'open world', 'exploration', 'role-playing']::text[]),
  ('elden-ring', 'Elden Ring', 'RPG • Action', 'RPG', ARRAY['RPG', 'Action', 'Adventure', 'Open World']::text[], 'Journey through the Lands Between, an expansive fantasy realm filled with hidden dungeons and formidable foes. Discover its history at your own pace in this challenging action role-playing adventure.', 'https://cdn.akamai.steamstatic.com/steam/apps/1245620/header.jpg', 'https://store.steampowered.com/app/1245620/', ARRAY['open world', 'fantasy', 'challenging', 'souls-like']::text[]),
  ('baldurs-gate-3', 'Baldur''s Gate 3', 'RPG • Turn-based', 'RPG', ARRAY['RPG', 'Adventure', 'Strategy']::text[], 'Gather a party and shape a Dungeons & Dragons story through tactical battles and meaningful choices. Your decisions can change relationships, quests, and the fate of the Sword Coast.', 'https://cdn.akamai.steamstatic.com/steam/apps/1086940/header.jpg', 'https://store.steampowered.com/app/1086940/', ARRAY['fantasy', 'choices', 'co-op', 'turn-based']::text[]),
  ('final-fantasy-vii-remake', 'Final Fantasy VII Remake Intergrade', 'RPG • Action', 'RPG', ARRAY['RPG', 'Action', 'Adventure']::text[], 'Return to Midgar in a reimagining of the opening chapter of Final Fantasy VII. Switch between party members and combine real-time action with tactical commands.', 'https://cdn.akamai.steamstatic.com/steam/apps/1462040/header.jpg', 'https://store.steampowered.com/app/1462040/', ARRAY['fantasy', 'story rich', 'party-based', 'action']::text[]),
  ('persona-5-royal', 'Persona 5 Royal', 'RPG • Turn-based', 'RPG', ARRAY['RPG', 'Adventure']::text[], 'Live a double life as a Tokyo student and a Phantom Thief in this stylish role-playing game. Build friendships by day and explore supernatural palaces in turn-based battles.', 'https://cdn.akamai.steamstatic.com/steam/apps/1687950/header.jpg', 'https://store.steampowered.com/app/1687950/', ARRAY['anime', 'turn-based', 'story rich', 'japanese rpg']::text[]),
  ('dragon-age-inquisition', 'Dragon Age: Inquisition', 'RPG • Fantasy', 'RPG', ARRAY['RPG', 'Adventure', 'Strategy']::text[], 'Lead the Inquisition across a world torn by magical upheaval and political danger. Recruit companions, make consequential choices, and shape the future of Thedas.', 'https://cdn.akamai.steamstatic.com/steam/apps/1222690/header.jpg', 'https://store.steampowered.com/app/1222690/', ARRAY['fantasy', 'party-based', 'choices', 'story rich']::text[]),
  ('stardew-valley', 'Stardew Valley', 'Simulation • Farming', 'Simulation', ARRAY['Simulation', 'RPG']::text[], 'Leave the city behind, restore your grandfather''s farm, and get to know the people of Pelican Town. Grow crops, raise animals, fish, and make the countryside your own.', 'https://cdn.akamai.steamstatic.com/steam/apps/413150/header.jpg', 'https://store.steampowered.com/app/413150/', ARRAY['indie', 'cozy', 'farming', 'crafting']::text[]),
  ('the-sims-4', 'The Sims 4', 'Simulation • Life', 'Simulation', ARRAY['Simulation']::text[], 'Create Sims, design homes, and guide everyday lives in a flexible life simulation. The base game is free to play, with optional expansion content available separately.', 'https://cdn.akamai.steamstatic.com/steam/apps/1222670/header.jpg', 'https://store.steampowered.com/app/1222670/', ARRAY['life sim', 'creative', 'building', 'casual']::text[]),
  ('minecraft', 'Minecraft', 'Sandbox • Survival', 'Simulation', ARRAY['Simulation', 'Adventure', 'Survival']::text[], 'Shape a block-built world by gathering resources, crafting tools, and constructing whatever you imagine. Play creatively or try to survive nights filled with hostile creatures.', 'https://store-images.s-microsoft.com/image/apps.53095.13850085746326678.06e2dc5c-7997-46e9-a8e6-0e48b57cb13b.419e3c9d-9dd3-4a28-a9f3-a12350215871?q=90&w=600&h=900', 'https://www.minecraft.net/', ARRAY['sandbox', 'building', 'crafting', 'survival']::text[]),
  ('terraria', 'Terraria', 'Sandbox • Adventure', 'Adventure', ARRAY['Adventure', 'Simulation', 'Survival', 'Action']::text[], 'Dig, fight, explore, and build in a lively two-dimensional world. Discover materials, craft gear, and prepare for increasingly ambitious bosses and biomes.', 'https://cdn.akamai.steamstatic.com/steam/apps/105600/header.jpg', 'https://store.steampowered.com/app/105600/', ARRAY['sandbox', 'crafting', 'survival', 'pixel art']::text[]),
  ('animal-crossing-new-horizons', 'Animal Crossing: New Horizons', 'Simulation • Life', 'Simulation', ARRAY['Simulation', 'Adventure']::text[], 'Build a personal island getaway, decorate your home, and meet a cast of animal neighbors. The island changes with the seasons and invites relaxed, day-by-day play.', 'https://upload.wikimedia.org/wikipedia/en/1/1f/Animal_Crossing_New_Horizons.jpg', 'https://www.nintendo.com/us/store/products/animal-crossing-new-horizons-switch/', ARRAY['cozy', 'life sim', 'creative', 'island']::text[]),
  ('cities-skylines', 'Cities: Skylines', 'Simulation • City Builder', 'Simulation', ARRAY['Simulation', 'Strategy']::text[], 'Plan roads, neighborhoods, and services as your small settlement grows into a city. Balance budgets and infrastructure while responding to the needs of its residents.', 'https://cdn.akamai.steamstatic.com/steam/apps/255710/header.jpg', 'https://store.steampowered.com/app/255710/', ARRAY['city builder', 'management', 'creative', 'strategy']::text[]),
  ('planet-zoo', 'Planet Zoo', 'Simulation • Management', 'Simulation', ARRAY['Simulation', 'Strategy']::text[], 'Build a wildlife park, care for animals, and design habitats that meet their needs. Detailed construction tools let you create a zoo from the ground up.', 'https://cdn.akamai.steamstatic.com/steam/apps/703080/header.jpg', 'https://store.steampowered.com/app/703080/', ARRAY['animals', 'management', 'building', 'creative']::text[]),
  ('cyberpunk-2077', 'Cyberpunk 2077', 'RPG • Open World', 'RPG', ARRAY['RPG', 'Action', 'Open World']::text[], 'Become V, a mercenary navigating the neon-lit streets of Night City. Shape your build and relationships as an ambitious heist pulls you into a conflict over identity and power.', 'https://cdn.akamai.steamstatic.com/steam/apps/1091500/header.jpg', 'https://store.steampowered.com/app/1091500/', ARRAY['open world', 'sci-fi', 'story rich', 'role-playing']::text[]),
  ('red-dead-redemption-2', 'Red Dead Redemption 2', 'Action • Open World', 'Open World', ARRAY['Open World', 'Action', 'Adventure']::text[], 'Follow outlaw Arthur Morgan and the Van der Linde gang across a richly detailed American frontier. Explore, hunt, and make choices as the gang struggles to survive a changing world.', 'https://cdn.akamai.steamstatic.com/steam/apps/1174180/header.jpg', 'https://store.steampowered.com/app/1174180/', ARRAY['western', 'story rich', 'exploration', 'open world']::text[]),
  ('grand-theft-auto-v', 'Grand Theft Auto V', 'Action • Open World', 'Open World', ARRAY['Open World', 'Action']::text[], 'Switch between three distinct protagonists in the sprawling city of Los Santos and Blaine County. Its story mode blends heists, driving, and open-ended exploration.', 'https://cdn.akamai.steamstatic.com/steam/apps/271590/header.jpg', 'https://store.steampowered.com/app/271590/', ARRAY['crime', 'open world', 'action', 'driving']::text[]),
  ('ghost-of-tsushima', 'Ghost of Tsushima Director''s Cut', 'Action • Open World', 'Open World', ARRAY['Open World', 'Action', 'Adventure']::text[], 'Fight to protect Tsushima Island as samurai Jin Sakai during the Mongol invasion. Explore a cinematic landscape and choose how to balance honorable combat with stealth.', 'https://cdn.akamai.steamstatic.com/steam/apps/2215430/header.jpg', 'https://store.steampowered.com/app/2215430/', ARRAY['samurai', 'open world', 'stealth', 'story rich']::text[]),
  ('marvels-spider-man-remastered', 'Marvel''s Spider-Man Remastered', 'Action • Open World', 'Open World', ARRAY['Open World', 'Action', 'Adventure']::text[], 'Swing through a detailed Manhattan as Peter Parker faces a threat to the city. Fast-paced combat, acrobatic traversal, and a character-focused story bring this superhero adventure to life.', 'https://cdn.akamai.steamstatic.com/steam/apps/1817070/header.jpg', 'https://store.steampowered.com/app/1817070/', ARRAY['superhero', 'open world', 'action', 'story rich']::text[]),
  ('god-of-war', 'God of War', 'Action • Adventure', 'Action', ARRAY['Action', 'Adventure']::text[], 'Join Kratos and Atreus on a dangerous journey through the realms of Norse mythology. Their relationship develops alongside weighty combat and exploration.', 'https://cdn.akamai.steamstatic.com/steam/apps/1593500/header.jpg', 'https://store.steampowered.com/app/1593500/', ARRAY['mythology', 'story rich', 'combat', 'adventure']::text[]),
  ('assassins-creed-odyssey', 'Assassin''s Creed Odyssey', 'Action • RPG', 'Open World', ARRAY['Open World', 'Action', 'RPG', 'Adventure']::text[], 'Travel across ancient Greece as a mercenary caught in a war between Athens and Sparta. Explore islands, make story choices, and uncover a personal family history.', 'https://cdn.akamai.steamstatic.com/steam/apps/812140/header.jpg', 'https://store.steampowered.com/app/812140/', ARRAY['historical', 'open world', 'role-playing', 'exploration']::text[]),
  ('horizon-zero-dawn', 'Horizon Zero Dawn Complete Edition', 'Action • RPG', 'Open World', ARRAY['Open World', 'Action', 'RPG', 'Adventure']::text[], 'Join hunter Aloy as she investigates a wild world dominated by machine creatures. Track machines, uncover the past, and explore a distinctive post-apocalyptic landscape.', 'https://cdn.akamai.steamstatic.com/steam/apps/1151640/header.jpg', 'https://store.steampowered.com/app/1151640/', ARRAY['sci-fi', 'open world', 'exploration', 'story rich']::text[]),
  ('resident-evil-2', 'Resident Evil 2', 'Horror • Survival', 'Horror', ARRAY['Horror', 'Survival', 'Action']::text[], 'Survive a nightmare in Raccoon City as Leon and Claire uncover the truth behind a devastating outbreak. Resource management and tense exploration keep danger close.', 'https://cdn.akamai.steamstatic.com/steam/apps/883710/header.jpg', 'https://store.steampowered.com/app/883710/', ARRAY['survival horror', 'zombies', 'story rich', 'remake']::text[]),
  ('resident-evil-4', 'Resident Evil 4', 'Horror • Action', 'Horror', ARRAY['Horror', 'Survival', 'Action']::text[], 'Play as agent Leon S. Kennedy on a mission to rescue the president''s daughter in a remote European village. A tense mix of resourceful combat, exploration, and survival drives the journey.', 'https://cdn.akamai.steamstatic.com/steam/apps/2050650/header.jpg', 'https://store.steampowered.com/app/2050650/', ARRAY['survival horror', 'action', 'remake', 'zombies']::text[]),
  ('silent-hill-2', 'Silent Hill 2', 'Horror • Psychological', 'Horror', ARRAY['Horror', 'Adventure']::text[], 'Follow James Sunderland into the fog-shrouded town of Silent Hill after receiving a letter from his late wife. Psychological dread and unsettling encounters build a deeply personal mystery.', 'https://cdn.akamai.steamstatic.com/steam/apps/2124490/header.jpg', 'https://store.steampowered.com/app/2124490/', ARRAY['psychological horror', 'atmospheric', 'remake', 'story rich']::text[]),
  ('outlast', 'Outlast', 'Horror • Survival', 'Horror', ARRAY['Horror', 'Survival']::text[], 'Investigate the abandoned Mount Massive Asylum as journalist Miles Upshur. With no way to fight back, you must hide, observe, and find a route through the darkness.', 'https://cdn.akamai.steamstatic.com/steam/apps/238320/header.jpg', 'https://store.steampowered.com/app/238320/', ARRAY['survival horror', 'found footage', 'stealth', 'psychological']::text[]),
  ('outlast-2', 'Outlast 2', 'Horror • Survival', 'Horror', ARRAY['Horror', 'Survival']::text[], 'Search for answers in a remote settlement after a helicopter crash leaves journalist Blake Langermann stranded. Stealth and a night-vision camera are vital in a hostile landscape.', 'https://cdn.akamai.steamstatic.com/steam/apps/414700/header.jpg', 'https://store.steampowered.com/app/414700/', ARRAY['survival horror', 'stealth', 'psychological', 'found footage']::text[]),
  ('amnesia-the-dark-descent', 'Amnesia: The Dark Descent', 'Horror • Survival', 'Horror', ARRAY['Horror', 'Survival', 'Adventure']::text[], 'Wake in a desolate castle with no memory and a note instructing you to descend into its depths. Avoid what lurks there while managing your character''s dwindling sense of safety.', 'https://cdn.akamai.steamstatic.com/steam/apps/57300/header.jpg', 'https://store.steampowered.com/app/57300/', ARRAY['psychological horror', 'atmospheric', 'survival', 'stealth']::text[]),
  ('little-nightmares', 'Little Nightmares', 'Horror • Puzzle', 'Horror', ARRAY['Horror', 'Adventure', 'Puzzle']::text[], 'Guide Six through the Maw, a vast vessel inhabited by grotesque residents. Sneak, climb, and solve environmental puzzles in a haunting miniature world.', 'https://cdn.akamai.steamstatic.com/steam/apps/424840/header.jpg', 'https://store.steampowered.com/app/424840/', ARRAY['atmospheric', 'puzzle', 'stealth', 'dark']::text[]),
  ('little-nightmares-ii', 'Little Nightmares II', 'Horror • Puzzle', 'Horror', ARRAY['Horror', 'Adventure', 'Puzzle']::text[], 'Help Mono and Six cross a distorted world shaped by a mysterious transmission. Stealth, platforming, and environmental puzzles lead through its unsettling locations.', 'https://cdn.akamai.steamstatic.com/steam/apps/860510/header.jpg', 'https://store.steampowered.com/app/860510/', ARRAY['atmospheric', 'puzzle', 'stealth', 'dark']::text[]),
  ('phasmophobia', 'Phasmophobia', 'Horror • Co-op', 'Horror', ARRAY['Horror', 'Survival']::text[], 'Team up to investigate haunted locations and identify the ghost using evidence-gathering equipment. The investigation grows more dangerous as the haunting intensifies.', 'https://cdn.akamai.steamstatic.com/steam/apps/739630/header.jpg', 'https://store.steampowered.com/app/739630/', ARRAY['multiplayer', 'co-op', 'ghosts', 'investigation']::text[]),
  ('dead-space', 'Dead Space', 'Horror • Survival', 'Horror', ARRAY['Horror', 'Survival', 'Action']::text[], 'Explore the derelict USG Ishimura as engineer Isaac Clarke searches for his crew. Strategic dismemberment and scarce supplies turn every encounter into a fight to survive.', 'https://cdn.akamai.steamstatic.com/steam/apps/1693980/header.jpg', 'https://store.steampowered.com/app/1693980/', ARRAY['sci-fi', 'survival horror', 'remake', 'atmospheric']::text[]),
  ('the-forest', 'The Forest', 'Survival • Horror', 'Survival', ARRAY['Survival', 'Horror', 'Adventure']::text[], 'Stranded in a forest after a plane crash, search for your missing son and gather what you need to survive. Build shelter and explore a dangerous peninsula populated by hostile mutants.', 'https://cdn.akamai.steamstatic.com/steam/apps/242760/header.jpg', 'https://store.steampowered.com/app/242760/', ARRAY['crafting', 'open world', 'co-op', 'survival horror']::text[]),
  ('sons-of-the-forest', 'Sons of the Forest', 'Survival • Horror', 'Survival', ARRAY['Survival', 'Horror', 'Adventure']::text[], 'Search a remote island for a missing billionaire while crafting tools and building a place to defend. Explore alone or with friends as the island''s threats evolve.', 'https://cdn.akamai.steamstatic.com/steam/apps/1326470/header.jpg', 'https://store.steampowered.com/app/1326470/', ARRAY['crafting', 'open world', 'co-op', 'survival horror']::text[]),
  ('subnautica', 'Subnautica', 'Adventure • Survival', 'Survival', ARRAY['Survival', 'Adventure', 'Simulation']::text[], 'Crash-land on an alien ocean world and dive through its vivid, dangerous ecosystems. Gather resources, build underwater tools, and uncover what happened to your ship.', 'https://cdn.akamai.steamstatic.com/steam/apps/264710/header.jpg', 'https://store.steampowered.com/app/264710/', ARRAY['underwater', 'exploration', 'crafting', 'survival']::text[]),
  ('the-last-of-us-part-i', 'The Last of Us Part I', 'Action • Survival', 'Survival', ARRAY['Survival', 'Action', 'Adventure']::text[], 'Travel across a post-pandemic United States with Joel and Ellie in a story-driven survival adventure. Scavenge carefully and navigate encounters shaped by infected and human threats.', 'https://cdn.akamai.steamstatic.com/steam/apps/1888930/header.jpg', 'https://store.steampowered.com/app/1888930/', ARRAY['post-apocalyptic', 'story rich', 'survival', 'stealth']::text[]),
  ('portal-2', 'Portal 2', 'Puzzle • Platformer', 'Puzzle', ARRAY['Puzzle', 'Adventure']::text[], 'Solve inventive physics puzzles using a portal device in a series of test chambers. Sharp writing and cooperative challenges expand the original game''s ideas.', 'https://cdn.akamai.steamstatic.com/steam/apps/620/header.jpg', 'https://store.steampowered.com/app/620/', ARRAY['puzzle', 'physics', 'co-op', 'comedy']::text[]),
  ('the-witness', 'The Witness', 'Puzzle • Exploration', 'Puzzle', ARRAY['Puzzle', 'Adventure', 'Open World']::text[], 'Wake on a mysterious island covered in interconnected line puzzles. Explore its landscapes and learn the rules by observation, without hand-holding or a traditional quest log.', 'https://cdn.akamai.steamstatic.com/steam/apps/210970/header.jpg', 'https://store.steampowered.com/app/210970/', ARRAY['puzzle', 'open world', 'exploration', 'indie']::text[]),
  ('civilization-vi', 'Sid Meier''s Civilization VI', 'Strategy • 4X', 'Strategy', ARRAY['Strategy']::text[], 'Build a civilization from its first settlement through the space age in this turn-based strategy game. Expand, research, negotiate, and compete for victory across a changing map.', 'https://cdn.akamai.steamstatic.com/steam/apps/289070/header.jpg', 'https://store.steampowered.com/app/289070/', ARRAY['turn-based', '4X', 'management', 'history']::text[]),
  ('age-of-empires-iv', 'Age of Empires IV', 'Strategy • RTS', 'Strategy', ARRAY['Strategy']::text[], 'Lead a historical civilization through campaigns and real-time battles across the medieval era. Gather resources, develop your settlement, and adapt your army to the battlefield.', 'https://cdn.akamai.steamstatic.com/steam/apps/1466860/header.jpg', 'https://store.steampowered.com/app/1466860/', ARRAY['real-time strategy', 'historical', 'multiplayer', 'base building']::text[]),
  ('hades', 'Hades', 'Action • Roguelike', 'Action', ARRAY['Action', 'RPG']::text[], 'Battle out of the Underworld as Zagreus, combining weapons and boons from the gods of Olympus. Each escape attempt builds on an evolving story and changing combat challenges.', 'https://cdn.akamai.steamstatic.com/steam/apps/1145360/header.jpg', 'https://store.steampowered.com/app/1145360/', ARRAY['roguelike', 'mythology', 'fast-paced', 'indie']::text[]),
  ('slay-the-spire', 'Slay the Spire', 'Strategy • Deckbuilding', 'Strategy', ARRAY['Strategy', 'RPG']::text[], 'Build a deck as you climb a constantly changing tower filled with enemies and branching paths. Thoughtful card choices and relic combinations make every run different.', 'https://cdn.akamai.steamstatic.com/steam/apps/646570/header.jpg', 'https://store.steampowered.com/app/646570/', ARRAY['deckbuilder', 'roguelike', 'turn-based', 'indie']::text[]),
  ('forza-horizon-5', 'Forza Horizon 5', 'Racing • Open World', 'Racing', ARRAY['Racing', 'Open World']::text[], 'Race across a large, varied interpretation of Mexico in a festival built around cars and exploration. Discover events, collect vehicles, and tune your ride for different terrain.', 'https://cdn.akamai.steamstatic.com/steam/apps/1551360/header.jpg', 'https://store.steampowered.com/app/1551360/', ARRAY['open world', 'cars', 'arcade racing', 'multiplayer']::text[]),
  ('need-for-speed-heat', 'Need for Speed Heat', 'Racing • Open World', 'Racing', ARRAY['Racing', 'Action', 'Open World']::text[], 'Race through Palm City by day and risk illegal street events by night. Earn money in sanctioned races while outrunning the police after dark.', 'https://cdn.akamai.steamstatic.com/steam/apps/1222680/header.jpg', 'https://store.steampowered.com/app/1222680/', ARRAY['cars', 'street racing', 'open world', 'customization']::text[]),
  ('assetto-corsa', 'Assetto Corsa', 'Racing • Simulation', 'Racing', ARRAY['Racing', 'Simulation']::text[], 'Drive a selection of licensed cars on laser-scanned circuits in a focused racing simulation. Tune assists and setups to suit your experience and racing style.', 'https://cdn.akamai.steamstatic.com/steam/apps/244210/header.jpg', 'https://store.steampowered.com/app/244210/', ARRAY['cars', 'simulation', 'motorsport', 'multiplayer']::text[]),
  ('control', 'Control', 'Action • Supernatural', 'Action', ARRAY['Action', 'Adventure', 'Horror']::text[], 'Enter the shifting Oldest House as Jesse Faden searches for answers about her past. Master supernatural abilities and explore a mysterious federal bureau under siege.', 'https://cdn.akamai.steamstatic.com/steam/apps/870780/header.jpg', 'https://store.steampowered.com/app/870780/', ARRAY['supernatural', 'sci-fi', 'story rich', 'third-person shooter']::text[]),
  ('alan-wake', 'Alan Wake', 'Action • Psychological Horror', 'Horror', ARRAY['Horror', 'Action', 'Adventure']::text[], 'Search for your missing wife in the town of Bright Falls as thriller writer Alan Wake. A mysterious story unfolds through exploration and combat against shadowy enemies.', 'https://cdn.akamai.steamstatic.com/steam/apps/108710/header.jpg', 'https://store.steampowered.com/app/108710/', ARRAY['psychological horror', 'story rich', 'mystery', 'action']::text[]),
  ('dead-by-daylight', 'Dead by Daylight', 'Horror • Multiplayer', 'Horror', ARRAY['Horror', 'Survival']::text[], 'Take part in asymmetric multiplayer matches as either a lone killer or one of four survivors. Teamwork, stealth, and quick decisions determine who escapes the trial.', 'https://cdn.akamai.steamstatic.com/steam/apps/381210/header.jpg', 'https://store.steampowered.com/app/381210/', ARRAY['multiplayer', 'asymmetric', 'survival horror', 'online co-op']::text[]),
  ('outer-wilds', 'Outer Wilds', 'Adventure • Exploration', 'Adventure', ARRAY['Adventure', 'Puzzle', 'Open World']::text[], 'Explore a handcrafted solar system caught in a time loop and piece together the fate of an ancient civilization. Curiosity and observation, rather than upgrades, uncover its mysteries.', 'https://cdn.akamai.steamstatic.com/steam/apps/753640/header.jpg', 'https://store.steampowered.com/app/753640/', ARRAY['space', 'exploration', 'mystery', 'open world']::text[]),
  ('risk-of-rain-2', 'Risk of Rain 2', 'Action • Roguelike', 'Action', ARRAY['Action', 'Survival']::text[], 'Fight across an alien planet where each passing moment makes the hostile world more dangerous. Collect unpredictable items and build a run alone or with friends.', 'https://cdn.akamai.steamstatic.com/steam/apps/632360/header.jpg', 'https://store.steampowered.com/app/632360/', ARRAY['roguelike', 'co-op', 'sci-fi', 'third-person shooter']::text[])
ON CONFLICT (id) DO UPDATE SET
  title = EXCLUDED.title,
  genre = EXCLUDED.genre,
  category = EXCLUDED.category,
  categories = EXCLUDED.categories,
  description = EXCLUDED.description,
  image = EXCLUDED.image,
  link = EXCLUDED.link,
  tags = EXCLUDED.tags;

-- Verify total rows in public.games after the seed.
SELECT COUNT(*) AS total_games
FROM public.games;
